function makeCounter(start = 0) {
  let count = start;            // private, kept alive by the closures below
  return {
    increment: () => ++count,
    decrement: () => --count,
    value: () => count
  };
}

const a = makeCounter();
const b = makeCounter(10);
a.increment();
a.increment();
b.decrement();
console.log(a.value(), b.value()); // 2 9

const state = {
  user: { name: 'Ravi', address: { city: 'Pune', pin: '411001' } },
  prefs: { theme: 'dark' }
};

const next = {
  ...state,
  user: {
    ...state.user,
    address: { ...state.user.address, city: 'Delhi' }
  }
};

console.log(state.user.address.city);   // 'Pune'  (original untouched)
console.log(next.user.address.city);    // 'Delhi'
console.log(next.prefs === state.prefs); // true   (shared)
console.log(next.user === state.user);   // false  (copied on the path)

const cart = [
  { id: 1, name: 'Keyboard', price: 1500, qty: 1, inStock: true },
  { id: 2, name: 'Mouse', price: 600, qty: 2, inStock: true },
  { id: 3, name: 'Monitor', price: 9000, qty: 1, inStock: false }
];

const available = cart.filter(item => item.inStock);
const lines = available.map(item => `${item.name} x${item.qty}`);
const total = available.reduce((sum, item) => sum + item.price * item.qty, 0);
const canCheckout = available.length > 0 && cart.every(item => item.qty > 0);

console.log(lines);       // ['Keyboard x1', 'Mouse x2']
console.log(total);       // 2700
console.log(canCheckout); // true

